-- Seven Tome I dossiers. archive_content RLS is the server-side access boundary:
-- registration for all records; archive_level >= 1 or full_access for two records.
begin;

insert into public.archive_content (slug,title,body,registration_required,required_archive_level,published) values
('artifact-will','Меч Воли',$artifact${
  "title":"Меч Воли","summary":"Широкий палаш, откликающийся на внутреннюю силу Дана.","type":"Магическое оружие / палаш","owner":"Дан","status":"Известен по Тому I",
  "description":["Меч Воли представляет собой очень широкий палаш. Его клинок изготовлен из обсидиана, добывавшегося в вулканах, которых на территории мира уже не осталось. Рукоять выполнена из кожи дракона.","На оружии есть золотой элемент, позволяющий монахам наносить руны. Благодаря ширине палаш отчасти может служить щитом."],
  "properties":["Подстраивается под владельца и связан с его внутренней силой.","Состояние и эмоции Дана отражаются на оружии: оно может нагреваться и вспыхивать.","Дан способен притянуть меч к себе силой мысли."],
  "origin":["Первоначальное происхождение Меча Воли и точная технология его создания в материалах Тома I не установлены."],
  "note":"Состав рун и дополнительные свойства в подтверждённых сведениях не указаны."
}$artifact$::jsonb,true,0,true),
('artifact-harvest','Меч Жатвы',$artifact${
  "title":"Меч Жатвы","summary":"Раздвоенный клинок, поглощающий жизненную силу через ранение.","type":"Магическое оружие","owner":"Форелл / Дариус","status":"Известен по Тому I",
  "description":["У меча чёрная рукоять с фиолетовой обмоткой и серебряным элементом на конце. Обоюдоострое лезвие раздвоено; возле рукояти между его частями находится небольшой фиолетовый кристалл. Оружие сопровождает тёмно-фиолетовое свечение.","Раздвоенная конструкция делает клинок легче."],
  "properties":["Для извлечения энергии мечу нужен контакт с кровью или ранение противника; после ранения он вытягивает жизненную силу.","Оружие способно сохранять связь с ранее раненой целью.","Меч предупреждает владельца об опасности вибрацией; по мере поглощения силы его свечение усиливается.","Саморанение опасно для владельца: клинок начинает забирать и его жизненную силу. Воздействие прекращается, когда меч возвращают в ножны."],
  "origin":["Форелл сталкивается с оружием и загадочным фиолетовым кристаллом. После соединения кристалла с мечом артефакт приобретает завершённую форму и позднее передаётся Дариусу."],
  "note":"Создатель меча, происхождение кристалла и природа загадочного голоса не установлены."
}$artifact$::jsonb,true,0,true),
('artifact-elements','Посох стихий',$artifact${
  "title":"Посох стихий","summary":"Не источник силы, а ограничитель магии Моргеуса.","type":"Магический артефакт / ограничитель силы","owner":"Моргеус","status":"Известен по Тому I",
  "description":["Вокруг посоха находятся камни. Их вращение связано с работой артефакта: чем быстрее они движутся, тем больше магии Моргеуса посох поглощает."],
  "properties":["Сдерживает огромную силу Моргеуса и помогает ему контролировать её; не усиливает владельца.","Без ограничителя собственная сила Моргеуса может быть опасна в том числе для него самого.","В книге посох также показан при работе с окружающей магической средой и во время масштабных заклинаний."],
  "origin":["Происхождение посоха, создатель и материал вращающихся камней в подтверждённых сведениях не названы."],
  "note":"Приписывать посоху роль источника магии Моргеуса неверно: его установленная функция противоположна."
}$artifact$::jsonb,true,0,true),
('artifact-wishes','Книга желаний',$artifact${
  "title":"Книга желаний","summary":"Фрагментарная архивная запись об артефакте с неизвестным местонахождением.","type":"Магическая книга","owner":"Местонахождение неизвестно","status":"Местонахождение неизвестно · происхождение не установлено",
  "description":["Лиенна узнаёт о существовании Книги желаний, изучая древние книги в библиотеке у Драконьей горы. Из найденных сведений следует, что это чрезвычайно могущественный артефакт."],
  "properties":["Согласно обнаруженному упоминанию, Книга способна исполнить желание того, кто сумеет её получить."],
  "origin":["Лиенна не знает, где находится Книга. Упоминание побуждает её задуматься о поисках; происхождение артефакта не установлено."],
  "note":"Досье неполное. Архив I располагает лишь сведениями, доступными в первом томе."
}$artifact$::jsonb,true,1,true),
('artifact-dragons','Меч драконов',$artifact${
  "title":"Меч драконов","summary":"Длинная катана, откликающаяся на Лиенну огнём и жаром.","type":"Магическое оружие / дар драконов","owner":"Лиенна","status":"Известен по Тому I",
  "description":["Оружие представляет собой длинную катану из металла неизвестного происхождения желтоватого оттенка. Рукоять чёрная; на её конце — фигурка золотого дракона с глазами из красных драгоценных камней."],
  "properties":["Когда Лиенна обнажает меч, она способна принимать человеческий облик; после возвращения клинка в ножны она вновь принимает облик докаина.","Клинок горит ярким оранжевым пламенем. Он позволяет создавать и концентрировать огонь, выпускать огненные заряды и сильно нагреваться.","При попытке Дариуса воспользоваться мечом эти свойства не проявились."],
  "origin":["Изучив древние знания о драконах в Мёртвых землях, Лиенна во время битвы произнесла молитву хранителей пламени и попросила драконов о помощи. Драконья гора задрожала, после чего со стороны горы появился меч и упал рядом с ней. Взяв оружие, Лиенна ощутила жар, распространяющийся по телу."],
  "note":"Связь появления меча с молитвой показана в первом томе; точная природа связи Лиенны с драконами не объяснена."
}$artifact$::jsonb,true,0,true),
('artifact-frauster-crown','Корона Фраустера',$artifact${
  "title":"Корона Фраустера","summary":"Королевская регалия, известная также как «Корона мёртвых».","type":"Королевская регалия / магический артефакт","owner":"Короли Фраустера · в Томе I король Филк","status":"Известна по Тому I",
  "description":["Корона связана с особой силой королей Фраустера. Для полноценного обряда действующий король объединяет корону со своим королевским оружием."],
  "properties":["Позволяет взаимодействовать с умершими предшественниками и получать от них советы.","Связана с силой света; при определённых условиях позволяет воздействовать на недавно умерших.","Использование сильно истощает носителя и требует продолжительного восстановления.","Умершие способны влиять на разум носителя. Неспособность противостоять их влиянию может привести к тяжёлым последствиям."],
  "origin":["Артефакт является королевской регалией Фраустера. Его первоначальное происхождение в этом досье не установлено."],
  "note":"Опасность короны заключается не только в расходе сил, но и в воздействии умерших на сознание короля."
}$artifact$::jsonb,true,0,true),
('artifact-galdvin-crown','Корона короля Галдвина',$artifact${
  "title":"Корона короля Галдвина","summary":"Неполное досье о королевской регалии Майзервина.","type":"Королевская регалия / магический артефакт","owner":"Король Галдвин / Майзервин","status":"Точный механизм не установлен",
  "description":["Корона короля Галдвина, также называемая короной Майзервина, связана с королевской властью этого государства. Архив I фиксирует лишь наблюдавшиеся проявления, не объясняя устройство артефакта."],
  "properties":["При прикосновении другого носителя к короне по телу проходит сильный холод.","На короткий момент возникает ощущение, связанное с тем, что переживал Галдвин.","Наблюдается кратковременное голубое свечение глаз."],
  "origin":["Происхождение короны и её создатель в подтверждённых сведениях не установлены."],
  "note":"Наблюдаемых эффектов недостаточно, чтобы утверждать, будто корона передаёт всю силу Галдвина или даёт власть над льдом."
}$artifact$::jsonb,true,1,true)
on conflict (slug) do update set
  title=excluded.title,body=excluded.body,registration_required=excluded.registration_required,
  required_archive_level=excluded.required_archive_level,published=excluded.published,
  updated_at=now();

commit;
